// Refresh each search so joining an offline hotspot after launching the game works.
// Interface broadcasts include tethering interfaces; Wi-Fi gateways provide a unicast
// discovery path when the hotspot drops broadcasts. Never assume a fixed subnet.
public String[] AndroidThunkJava_XQPDiscoveryTargets() {
    java.util.LinkedHashSet<String> targets = new java.util.LinkedHashSet<String>();
    try {
        java.util.Enumeration<java.net.NetworkInterface> interfaces = java.net.NetworkInterface.getNetworkInterfaces();
        while (interfaces != null && interfaces.hasMoreElements()) {
            java.net.NetworkInterface iface = interfaces.nextElement();
            if (!iface.isUp() || iface.isLoopback()) continue;
            for (java.net.InterfaceAddress address : iface.getInterfaceAddresses()) {
                java.net.InetAddress broadcast = address.getBroadcast();
                if (broadcast instanceof java.net.Inet4Address) targets.add(broadcast.getHostAddress());
            }
        }
    } catch (Exception error) {
        android.util.Log.w("XQP", "Unable to enumerate LAN broadcasts", error);
    }
    try {
        android.net.ConnectivityManager manager = (android.net.ConnectivityManager)getSystemService(android.content.Context.CONNECTIVITY_SERVICE);
        if (manager != null) for (android.net.Network network : manager.getAllNetworks()) {
            android.net.NetworkCapabilities caps = manager.getNetworkCapabilities(network);
            if (caps == null || !caps.hasTransport(android.net.NetworkCapabilities.TRANSPORT_WIFI)) continue;
            android.net.LinkProperties link = manager.getLinkProperties(network);
            if (link == null) continue;
            for (android.net.RouteInfo route : link.getRoutes()) {
                java.net.InetAddress gateway = route.getGateway();
                if (gateway instanceof java.net.Inet4Address && !gateway.isAnyLocalAddress())
                    targets.add(gateway.getHostAddress());
            }
        }
    } catch (Exception error) {
        android.util.Log.w("XQP", "Unable to enumerate Wi-Fi gateways", error);
    }
    return targets.toArray(new String[0]);
}

// Reapply after lifecycle changes; the engine's legacy immersive flags alone
// can leave the portrait SurfaceView below the display cutout on some phones.
private void xqpApplyFullScreen() {
    final android.view.Window window = getWindow();
    if (android.os.Build.VERSION.SDK_INT >= 28) {
        android.view.WindowManager.LayoutParams params = window.getAttributes();
        params.layoutInDisplayCutoutMode = android.os.Build.VERSION.SDK_INT >= 30
            ? android.view.WindowManager.LayoutParams.LAYOUT_IN_DISPLAY_CUTOUT_MODE_ALWAYS
            : android.view.WindowManager.LayoutParams.LAYOUT_IN_DISPLAY_CUTOUT_MODE_SHORT_EDGES;
        window.setAttributes(params);
    }
    window.addFlags(android.view.WindowManager.LayoutParams.FLAG_DRAWS_SYSTEM_BAR_BACKGROUNDS);
    window.setStatusBarColor(android.graphics.Color.TRANSPARENT);
    window.setNavigationBarColor(android.graphics.Color.TRANSPARENT);
    if (android.os.Build.VERSION.SDK_INT >= 29) {
        window.setStatusBarContrastEnforced(false);
        window.setNavigationBarContrastEnforced(false);
    }
    if (android.os.Build.VERSION.SDK_INT >= 30) {
        window.setDecorFitsSystemWindows(false);
        android.view.WindowInsetsController controller = window.getInsetsController();
        if (controller != null) {
            controller.setSystemBarsBehavior(android.view.WindowInsetsController.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE);
            controller.hide(android.view.WindowInsets.Type.systemBars());
        }
    }
    window.getDecorView().setSystemUiVisibility(
        android.view.View.SYSTEM_UI_FLAG_LAYOUT_STABLE
        | android.view.View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN
        | android.view.View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION
        | android.view.View.SYSTEM_UI_FLAG_FULLSCREEN
        | android.view.View.SYSTEM_UI_FLAG_HIDE_NAVIGATION
        | android.view.View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY);
    window.getDecorView().requestApplyInsets();
}

@Override
public void onWindowFocusChanged(boolean hasFocus) {
    super.onWindowFocusChanged(hasFocus);
    if (hasFocus) xqpApplyFullScreen();
}
